relations.meaning:
הקורסים הזמינים.
`category` (למשל 'Data Science', 'AI', 'Programming');
`level` (Beginner / Intermediate / Advanced); `hours` — שעות לימוד.

options.value:
SELECT first_name
FROM Users
WHERE user_id IN (
  SELECT user_id
  FROM Enrollments
  WHERE progress < 50
    AND course_id IN (
      SELECT course_id FROM Courses WHERE category = 'Data Science'
    )
);

SELECT country
FROM Users
GROUP BY registration_year = 2023 AND country != 'Israel';

SELECT course_title
FROM Courses
WHERE course_id IN (
  SELECT course_id FROM Enrollments WHERE progress = 100
);

SELECT course_title
FROM Enrollments
WHERE progress = 0;

SELECT course_title
FROM Courses
WHERE course_id IN (
  SELECT enrollment_id FROM Enrollments WHERE status = 'withdrawn'
);

SELECT first_name, course_title
FROM Enrollments
WHERE status = 'withdrawn';

CREATE VIEW course_instructor_view AS
SELECT course_title, full_name, hire_date
FROM Courses JOIN Instructors USING(course_id);

SELECT course_title
FROM Courses
WHERE course_id IN (
  SELECT course_id FROM Enrollments GROUP BY course_id HAVING COUNT(*) = 1
);

SELECT course_title
FROM Courses C
WHERE EXISTS (
  SELECT * FROM Enrollments E
  WHERE C.course_id = E.course_id
);

SELECT course_title
FROM Courses C
WHERE NOT EXISTS (
  SELECT * FROM Users U
  WHERE NOT EXISTS (
    SELECT * FROM Enrollments E
    WHERE E.user_id = U.user_id AND E.course_id = C.course_id
  )
);

SELECT course_title
FROM Courses
WHERE course_id IN (SELECT course_id FROM Enrollments WHERE user_id IS NULL);

SELECT course_title
FROM Courses
WHERE EXISTS (SELECT * FROM Enrollments WHERE course_id IS NULL);

SELECT course_title
FROM Courses
WHERE course_id NOT IN (SELECT course_id FROM Enrollments);
